// -----------------------------------------------------------------------------
// Program.cs
// -----------------------------------------------------------------------------
// This file defines the entry point and command‑line interface for the Bovis web
// application. It provides commands for checking configuration, managing
// configuration properties, and starting the web server. The file also contains
// helper methods for loading JSON configuration files and building the
// WebApplicationBuilder with logging, configuration database, and optional
// Bovis database setup.
// -----------------------------------------------------------------------------
using Bovis.Interfaces;
using Bovis.Interfaces.Configuration;
using Bovis.Storage;
using Bovis.Web.Areas.Identity;
using Bovis.Web.Data;
using Bovis.Web.Util;
using DbTools.DbUrl;
using Microsoft.AspNetCore.Authentication.Negotiate;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.HttpOverrides;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.FileProviders;
using System.CommandLine;
using System.CommandLine.Builder;
using System.Text.RegularExpressions;
using MessageDb = Bovis.Logging.MessageDb;

namespace Bovis.Web;

/// <summary>
/// Main program class containing command definitions and server startup logic.
/// </summary>
public partial class Program
{
    /// <summary>
    /// Command that checks the application configuration.
    /// </summary>
    /// <param name="withdb">If true, also attempts to set up the database connection.</param>
    /// <returns>0 on success, 1 on failure.</returns>
    [Command("check", "Check configuration.")]
    public static int CmdCheck
            ([Option("--withdb", "test value")] bool withdb = false)
    {
        try
        {
            var builder = CreateAndSetupBuilder([], withdb);
            return 0;
        }
        catch (Exception ex)
        {
            MessageDb.ShowException(ex);
            return 1;
        }
    }

